/**
 * Title: Equidistant Space - Zen Tribute
 * Description: A generative study on balance and decay.
 * Every single line is commented for clarity.
 */

let dt; // Variable to hold the Delaunay triangulation object
let nodes = []; // Array to store the points (nodes) of the graph
let edges = []; // Array to store the edges connecting the nodes
let tris = []; // Array to store the calculated triangles

const FADE_IN = 10000; // Duration of the fade-in phase (10 seconds)
const MAIN_STAY = 20000; // Duration of the main drawing phase (30 seconds)
const FADE_OUT = 20000; // Duration of the fade-out phase (10 seconds)
const CYCLE = FADE_IN + MAIN_STAY + FADE_OUT; // Total duration of one cycle (50 seconds)

let startTime; // Variable to track when the current cycle started

function setup() { // Initialization function called once at the start
  createCanvas(windowWidth, windowHeight); // Create a canvas that fills the browser window
  frameRate(12); // Set the simulation to run at 12 frames per second
  initUniverse(); // Call custom function to initialize the geometry
} // End of setup function

function initUniverse() { // Function to reset the simulation state
  dt = new Delaunay(); // Create a fresh instance of the Delaunay algorithm
  nodes = []; // Clear the existing nodes array
  edges = []; // Clear the existing edges array
  tris = []; // Clear the existing triangles array
  for (let i = 0; i < 35; i++) { // Loop to create initial points
    dt.insert(width / 2 + random(-10, 10), height / 2 + random(-10, 10)); // Insert points near the center
  } // End of point insertion loop
  startTime = millis(); // Record the current time as the start of the cycle
  background(10, 10, 15, 6); // Paint the background solid black to start fresh
} // End of initUniverse function

function draw() {
  // === Variant 4: Dynamic Feedback Trail ===
  // Lower background clear to force deep visual echoing
 // Main animation loop called repeatedly
  let elapsed = (millis() - startTime) % CYCLE; // Calculate how many milliseconds passed in the current cycle

  if (millis() - startTime > CYCLE) { // Check if the total cycle time has been exceeded
    initUniverse(); // Restart the universe if the cycle is complete
    return; // Exit the current draw loop early
  } // End of cycle check

  let alphaVal = 0; // Initialize alpha value for transparency control
  if (elapsed < FADE_IN) { // Phase 1: Fading in
    alphaVal = map(elapsed, 0, FADE_IN, 0, 1); // Gradually increase alpha from 0 to 1
  } else if (elapsed < FADE_IN + MAIN_STAY) { // Phase 2: Fully visible
    alphaVal = 1; // Keep alpha at maximum
  } else { // Phase 3: Fading out
    alphaVal = map(elapsed, FADE_IN + MAIN_STAY, CYCLE, 1, 0); // Gradually decrease alpha from 1 to 0
  } // End of alpha calculation

  push(); // Save current drawing state
  fill(0, 5); // Set fill color to black with very low opacity for trails
  noStroke(); // Disable outlines for the trail rectangle
  rect(0, 0, width, height); // Draw a full-screen rectangle to create motion blur
  pop(); // Restore previous drawing state

  if (!(keyIsPressed && key === ' ')) { // Check if the spacebar is NOT being held
    updateGraph(); // Update the positions and geometry if not paused
  } // End of pause check

  noFill(); // Disable filling for the geometric lines
  strokeWeight(0.6); // Set a very fine line thickness

  for (let e of edges) { // Iterate through every edge in the graph
    if (!e.inT) continue; // Skip edges that aren't part of a valid triangle
    stroke(random(255), 180 * alphaVal); // Apply monochrome flickering and current fade alpha
    let t1 = e.inT; // Reference the triangle on one side of the edge
    let ee = e.invE; // Reference the opposite edge (twin)
    if (ee && ee.inT) { // If there is a neighboring triangle
      let t2 = ee.inT; // Reference the neighboring triangle
      line(t1.c_cx, t1.c_cy, t2.c_cx, t2.c_cy); // Draw line between the two triangle circumcenters
    } else { // If the edge is on the boundary (convex hull)
      let dx = -(e.p2.y - e.p1.y) * 0.3; // Calculate a perpendicular offset x
      let dy = (e.p1.x - e.p2.x) * 0.3; // Calculate a perpendicular offset y
      line(t1.c_cx, t1.c_cy, t1.c_cx + dx, t1.c_cy + dy); // Draw line extending outwards
    } // End of line drawing logic
  } // End of edges loop

  noStroke(); // Disable outlines for the points
  for (let n of nodes) { // Iterate through every node in the graph
    fill(random(255), 180 * alphaVal); // Apply monochrome flickering to the node
    let d = dist(n.x, n.y, width / 2, height / 2); // Calculate distance from the center
    let dotSize = map(d, 0, width / 2, 2.8, 1.0); // Determine size based on distance
    ellipse(n.x, n.y, dotSize, dotSize); // Draw the point as a small circle
  } // End of nodes loop
} // End of draw function

function updateGraph() { // Function to handle physics and re-triangulation
  if (nodes.length < 180 && frameCount % 100 === 0) { // Condition to add new points slowly
    dt.insert(width / 2 + random(-2, 2), height / 2 + random(-2, 2)); // Add a point at the center
  } // End of point addition
  syncData(); // Synchronize the local arrays with the Delaunay object's data
  let D = Math.sqrt(nodes.length) || 1; // Calculate a density factor
  let mouseV = createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))); // Capture current mouse position
  for (let e of edges) { // Physics loop: Repulsion between points
    let p1 = createVector(e.p1.x, e.p1.y); // Current position of point 1
    let p2 = createVector(e.p2.x, e.p2.y); // Current position of point 2
    let diff = p5.Vector.sub(p2, p1); // Vector pointing from p1 to p2
    let rr = diff.magSq(); // Squared distance between points
    let thresh = (width * height) / (D * D); // Threshold for repulsion
    if (rr < thresh) rr /= 1.5; // Amplify force if points are too close
    if (rr > 0.1) { // Prevent division by zero or extreme forces
      let f = (width * D) / rr * 0.0012; // Calculate a very weak repulsion force
      let move = diff.mult(f); // Scale the direction vector by the force
      e.p1.x -= move.x; e.p1.y -= move.y; // Move point 1 away
      e.p2.x += move.x; e.p2.y += move.y; // Move point 2 away
    } // End of repulsion logic
    let dM = p5.Vector.dist(p1, mouseV); // Distance from point to mouse
    if (dM < 250) { // If the mouse is close enough
      let mF = p5.Vector.sub(p1, mouseV).normalize().mult(map(dM, 0, 250, 0.02, 0)); // Weak mouse repulsion
      e.p1.x += mF.x; e.p1.y += mF.y; // Apply mouse force
    } // End of mouse repulsion
  } // End of physics loop
  let xlo = width, ylo = height, xhi = 0, yhi = 0; // Initialize bounding box variables
  for (let n of nodes) { // Find the current extent of all points
    xlo = min(xlo, n.x); ylo = min(ylo, n.y); // Update minimums
    xhi = max(xhi, n.x); yhi = max(yhi, n.y); // Update maximums
  } // End of extent search
  let tmp = [...nodes]; // Create a shallow copy of the nodes array
  if (tmp.length > 150 && frameCount % 200 === 0) { // Condition to remove points slowly
    tmp.splice(floor(random(tmp.length)), 1); // Remove one random point
  } // End of point removal
  dt.clear(); // Clear the Delaunay triangulation to rebuild it
  let rw = (xhi - xlo) || 1; // Width of the current bounding box
  let rh = (yhi - ylo) || 1; // Height of the current bounding box
  for (let n of tmp) { // Re-insert points with a slight scaling effect
    let tx = (n.x - xlo) * (width - 200) / rw + 100; // Calculate target x position
    let ty = (n.y - ylo) * (height - 200) / rh + 100; // Calculate target y position
    dt.insert(lerp(n.x, tx, 0.0012), lerp(n.y, ty, 0.0012)); // Move slowly toward target and insert
  } // End of re-insertion loop
  syncData(); // Final sync for the frame
} // End of updateGraph function

function windowResized() { // Called when the browser window is resized
  resizeCanvas(windowWidth, windowHeight); // Adjust canvas size
  background(10, 10, 15, 6); // Clear background to prevent stretching artifacts
} // End of windowResized function

function syncData() { // Helper to map internal library data to globals
  nodes = dt.nodes; // Reference the Delaunay nodes
  edges = dt.edges; // Reference the Delaunay edges
  tris = dt.tris; // Reference the Delaunay triangles
} // End of syncData function

class DelaunayNode { // Class representing a point in space
  constructor(x, y) { this.x = x; this.y = y; this.anEdge = null; } // Initialize coords and edge reference
  distance(px, py) { return dist(this.x, this.y, px, py); } // Method to calculate distance to a coordinate
} // End of Node class

class DelaunayEdge { // Class representing a connection between points
  constructor(p1, p2) { // Initialize with two points
    this.p1 = p1; this.p2 = p2; // Store point references
    this.invE = null; this.nextE = null; this.nextH = null; this.inT = null; // Initialize relationship pointers
    this.update(); // Calculate linear equation parameters
  } // End of constructor
  update() { // Calculate parameters for side-of-line tests
    this.a = this.p2.y - this.p1.y; // Coeff a
    this.b = this.p1.x - this.p2.x; // Coeff b
    this.c = this.p2.x * this.p1.y - this.p1.x * this.p2.y; // Coeff c
    this.p1.anEdge = this; // Link point to this edge
  } // End of update method
  onSide(n) { // Determine which side of the edge a node lies on
    let s = this.a * n.x + this.b * n.y + this.c; // Calculate line equation
    return s > 0.01 ? 1 : (s < -0.01 ? -1 : 0); // Return 1 (left), -1 (right), or 0 (on line)
  } // End of onSide method
  rink(e) { this.invE = e; if (e) e.invE = this; } // Link this edge with its twin (opposite direction)
  makeSymm() { // Create a symmetric twin edge
    let e = new DelaunayEdge(this.p2, this.p1); // New edge in reverse direction
    this.rink(e); // Link them
    return e; // Return the new edge
  } // End of makeSymm method
} // End of Edge class

class DelaunayTriangle { // Class representing a triangle in the mesh
  constructor(e1, e2, e3, edgeList) { // Initialize with three edges
    this.e1 = e1; this.e2 = e2; this.e3 = e3; // Store edge references
    e1.nextE = e2; e2.nextE = e3; e3.nextE = e1; // Link edges in a loop
    e1.inT = e2.inT = e3.inT = this; // Link edges back to this triangle
    if (edgeList) edgeList.push(e1, e2, e3); // Add edges to the global list if provided
    this.updateCircle(); // Calculate the circumcircle
  } // End of constructor
  updateCircle() { // Find the circle that passes through all 3 vertices
    let x1 = this.e1.p1.x, y1 = this.e1.p1.y; // Vertex 1
    let x2 = this.e2.p1.x, y2 = this.e2.p1.y; // Vertex 2
    let x3 = this.e3.p1.x, y3 = this.e3.p1.y; // Vertex 3
    let det = (x2 - x1) * (y3 - y2) - (y2 - y1) * (x3 - x2); // Matrix determinant
    if (abs(det) < 0.001) det = det < 0 ? -0.001 : 0.001; // Avoid division by zero
    let b1 = (x1 + x2) * (x2 - x1) + (y1 + y2) * (y2 - y1); // Intermediate value 1
    let b2 = (x2 + x3) * (x3 - x2) + (y2 + y3) * (y3 - y2); // Intermediate value 2
    this.c_cx = (b1 * (y3 - y2) - b2 * (y2 - y1)) / det / 2; // Center X
    this.c_cy = (b2 * (x2 - x1) - b1 * (x3 - x2)) / det / 2; // Center Y
    this.c_r = dist(x1, y1, this.c_cx, this.c_cy); // Radius
  } // End of updateCircle method
} // End of Triangle class

class Delaunay { // Main manager class for the triangulation algorithm
  constructor() { this.nodes = []; this.edges = []; this.tris = []; this.hullStart = null; this.actE = null; } // Init state
  clear() { this.nodes = []; this.edges = []; this.tris = []; this.hullStart = null; } // Reset state
  insert(px, py) { // Insert a new point into the mesh
    let nd = new DelaunayNode(px, py); // Create a node object
    this.nodes.push(nd); // Add to the nodes list
    if (this.nodes.length < 3) return; // Need at least 3 points for a triangle
    if (this.nodes.length === 3) { // Special case for the very first triangle
      let p1 = this.nodes[0], p2 = this.nodes[1], p3 = this.nodes[2]; // Get points
      let e1 = new DelaunayEdge(p1, p2); // Create first edge
      if (e1.onSide(p3) === 0) { this.nodes.pop(); return; } // Skip if collinear
      if (e1.onSide(p3) === -1) { [p1, p2] = [p2, p1]; e1.update(); } // Ensure counter-clockwise
      let e2 = new DelaunayEdge(p2, p3), e3 = new DelaunayEdge(p3, p1); // Create remaining edges
      e1.nextH = e2; e2.nextH = e3; e3.nextH = e1; // Link for the convex hull
      this.hullStart = e1; // Set starting hull edge
      this.tris.push(new DelaunayTriangle(e1, e2, e3, this.edges)); // Create triangle
      return; // Done
    } // End of initial triangle case
    let found = this.search(nd); // Search for where the point lies
    if (found > 0) this.expandTri(this.actE, nd); // If inside, split the triangle
    else this.expandHull(nd); // If outside, expand the convex hull
  } // End of insert method
  search(nd) { // Find the triangle containing the point (iterative walk)
    if (this.edges.length === 0) return -1; // No edges to search
    let curr = this.edges[0]; // Start at the first edge
    let visited = new Set(); // Prevent infinite loops
    while (curr && !visited.has(curr)) { // Loop until point found or hull reached
      visited.add(curr); // Mark as visited
      if (curr.nextE && curr.nextE.onSide(nd) === -1) { // Check if point is to the right
        if (curr.nextE.invE) { curr = curr.nextE.invE; continue; } // Move to neighboring triangle
        else { this.actE = curr.nextE; return -1; } // Point is outside the hull
      } // End of side check
      if (curr.nextE && curr.nextE.nextE && curr.nextE.nextE.onSide(nd) === -1) { // Check other edge
        if (curr.nextE.nextE.invE) { curr = curr.nextE.nextE.invE; continue; } // Move to neighboring triangle
        else { this.actE = curr.nextE.nextE; return -1; } // Point is outside the hull
      } // End of side check
      this.actE = curr; return 2; // Point is inside current triangle
    } // End of while loop
    return -1; // Default to outside
  } // End of search method
  expandTri(e, nd) { // Split a triangle into three new ones
    let t = e.inT; if (!t) return; // Guard against null
    let e1 = t.e1, e2 = t.e2, e3 = t.e3; // Get edges of the triangle
    let idx = this.tris.indexOf(t); if (idx > -1) this.tris.splice(idx, 1); // Remove old triangle
    let e10 = new DelaunayEdge(e1.p1, nd), e20 = new DelaunayEdge(e2.p1, nd), e30 = new DelaunayEdge(e3.p1, nd); // Inner edges
    this.tris.push(new DelaunayTriangle(e1, e20, e10.makeSymm(), this.edges)); // New triangle 1
    this.tris.push(new DelaunayTriangle(e2, e30, e20.makeSymm(), this.edges)); // New triangle 2
    this.tris.push(new DelaunayTriangle(e3, e10, e30.makeSymm(), this.edges)); // New triangle 3
  } // End of expandTri method
  expandHull(nd) { // Expand the mesh to include a point outside the current hull
    let e = this.hullStart, last = null, first = null, curr = e; if (!curr) return; // Guard
    do { // Walk along the hull
      if (curr.onSide(nd) === -1) { // If point can see this edge
        let e1 = curr.makeSymm(), e2 = new DelaunayEdge(curr.p1, nd), e3 = new DelaunayEdge(nd, curr.p2); // New edges
        if (!first) this.hullStart = e2; else first.rink(e2); // Update hull start and links
        first = e3; // Store last edge created
        this.tris.push(new DelaunayTriangle(e1, e2, e3, this.edges)); // Create triangle connecting to hull
      } else { if (first) break; last = curr; } // Track where to stop
      curr = curr.nextH; // Move to next hull edge
    } while (curr !== e && curr != null); // Loop around the hull
    if (last && first) { last.nextH = first; first.nextH = curr; } // Fix hull pointers
  } // End of expandHull method
} // End of Delaunay class

